insert into public.questions(id,category_id,question_type,question_text,difficulty,explanation,slug,is_practice,status) select '935a88eb-af88-5cc8-8957-f68ba9ae6047',id,'coding','Write a function that returns the maximum of a nonempty integer array. Example: [-7, -2, -9] → -2. State how you handle an empty array. Aim for O(n) time and O(1) extra space.','medium','Start best at the first element. For every later element, replace best if that element is larger. Return best. Reject an empty array or return an optional result according to your stated contract. Test all-negative values, a single value and duplicates. The invariant is that best is the maximum of the visited prefix.','maximum-array-scan',true,'published' from public.categories where slug='arrays' on conflict(id) do nothing;
insert into public.questions(id,category_id,question_type,question_text,difficulty,explanation,slug,is_practice,status) select 'd44fc2c6-3a3a-5727-a30f-a32071991499',id,'coding','Given an ascending sorted array that may contain duplicates, return the index of the first occurrence of a target, or -1 if absent. Example: [1, 2, 2, 2, 5], target 2 → 1. Aim for O(log n) time.','medium','Use binary search with an answer initialised to -1. When a[mid] equals target, store mid and continue searching left by setting high=mid-1. When it is smaller, set low=mid+1; otherwise set high=mid-1. Continuing left on equality finds the first occurrence. Verify empty input, target absent, all equal and matches at both ends.','first-binary-search-match',true,'published' from public.categories where slug='algorithms' on conflict(id) do nothing;
insert into public.questions(id,category_id,question_type,question_text,difficulty,explanation,slug,is_practice,status) select '7c586a07-0431-54dd-a624-3b1971306d33',id,'coding','Write a function to check whether a string is a palindrome, comparing characters exactly as provided. Examples: "level" → true; "Level" → false; empty string → true. Aim for O(n) time and O(1) extra space.','medium','Place one pointer at each end. While left<right, return false on a mismatch; otherwise move both pointers inward. Return true when the pointers meet or cross. This exact-character contract is case-sensitive and includes spaces. Define a different normalization step explicitly if a future requirement asks you to ignore case or punctuation.','palindrome-two-pointers',true,'published' from public.categories where slug='strings' on conflict(id) do nothing;
insert into public.blog_posts(title,slug,description,body,status) values('How to turn a mock result into a study plan','turn-mock-results-into-study-plan','Use your mistakes to choose the next lesson, practice set and retest.','Begin with the questions you missed, not just the final score. Classify each mistake: missing concept, wrong method, arithmetic slip, misunderstood wording or time pressure. Keep a short error log with the topic, cause and the method you will try next.
